{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Wie lange dauert eine Display-Reparatur?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "In der Regel 30 Minuten bis zu einer Stunde. Bei gängigen Modellen können Sie Ihr Gerät oft direkt wieder mitnehmen."
      }
    },
    {
      "@type": "Question",
      "name": "Kostet ein Kostenvoranschlag etwas?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Ein Kostenvoranschlag kostet 25 €. Lassen Sie die Reparatur anschließend bei uns durchführen, ziehen wir diese 25 € vom Reparaturpreis wieder ab."
      }
    },
    {
      "@type": "Question",
      "name": "Bekomme ich Garantie auf die Reparatur?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Ja. Auf die meisten Reparaturen geben wir 6 Monate Garantie."
      }
    },
    {
      "@type": "Question",
      "name": "Kann ich mein altes Handy in Zahlung geben?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Ja, gerne. Sie können Ihr altes Gerät bei uns in Zahlung geben und den Wert direkt anrechnen lassen."
      }
    },
    {
      "@type": "Question",
      "name": "Repariert ihr auch, während ich warte?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Ja. Viele Reparaturen erledigen wir, während Sie warten – am besten trinken Sie in der Zwischenzeit einen Kaffee in der Nähe."
      }
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "How long does a display repair take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Usually 30 minutes to an hour. For common models you can often take your device with you right away."
      }
    },
    {
      "@type": "Question",
      "name": "Does a cost estimate cost anything?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "A cost estimate costs €25. If you then have the repair done with us, we deduct these €25 from the repair price."
      }
    },
    {
      "@type": "Question",
      "name": "Do I get a warranty on the repair?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We give 6 months warranty on most repairs."
      }
    },
    {
      "@type": "Question",
      "name": "Can I trade in my old phone?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, gladly. You can trade in your old device with us and have its value credited directly."
      }
    },
    {
      "@type": "Question",
      "name": "Do you also repair while I wait?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. We complete many repairs while you wait – a good time to grab a coffee nearby."
      }
    }
  ]
}
